// Helper to get dynamic read time styles
const getReadTimeStats = (readTimeStr: string) => {
    const mins = parseInt(readTimeStr.split(' ')[0]) || 5;
    let colorClass = 'text-emerald-500';
    let bgClass = 'bg-emerald-500/10';
    let pulseClass = 'animate-pulse';
    let intensity = (mins / 10) * 100; // Cap at 10 mins for visual scale

    if (mins < 5) {
        colorClass = 'text-emerald-500';
        bgClass = 'bg-emerald-500/10';
    } else if (mins < 8) {
        colorClass = 'text-vibrant-orange';
        bgClass = 'bg-vibrant-orange/10';
    } else {
        colorClass = 'text-red-500';
        bgClass = 'bg-red-500/10';
    }

    return { mins, colorClass, bgClass, pulseClass, intensity: Math.min(intensity, 100) };
};

const ReadTimeBadge: React.FC<{ readTime: string; className?: string }> = ({ readTime, className = "" }) => {
    const { mins, colorClass, bgClass, intensity } = getReadTimeStats(readTime);

    return (
        <div className={`flex flex-col gap-1.5 ${className}`}>
            <div className="flex items-center gap-1.5">
                <div className={`p-1 rounded-md ${bgClass} ${colorClass}`}>
                    <Clock className="w-3.5 h-3.5" />
                </div>
                <span className={`text-[10px] font-bold uppercase tracking-wider ${colorClass}`}>
                    {readTime}
                </span>
            </div>
            {/* Visual Progress/Intensity Bar */}
            <div className="h-1 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                <div 
                    className={`h-full transition-all duration-1000 ${colorClass.replace('text', 'bg')}`} 
                    style={{ width: `${intensity}%` }}
                />
            </div>
        </div>
    );
};

