  const [connectedApps, setConnectedApps] = useState<string[]>(user.connectedApps || ['whatsapp', 'gmail']);

  const handleSave = () => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setSuccess(true);
      setTimeout(() => setSuccess(false), 3000);
      onSave({
          name: profileData.name,
          location: profileData.location,
          connectedApps
      });
    }, 1500);
  };

